1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	
14	const DEDUCTIBLE_PER_DAMAGE = 100;
15	const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
16	const REDUCED_REIMBURSEMENT_RATE = 0.5;
17	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
18	
19	const CURSE_SURCHARGE_RATE = 0.5;
20	
21	const HIGH_ENCHANTMENT_LEVEL = 5;
22	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
23	
24	const LOYALTY_YEARS = 2;
25	const LOYALTY_DISCOUNT_RATE = 0.2;
26	
27	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
28	
29	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
30	
31	const COMPONENT_BASE_PREMIUM = 25;
32	const COMPONENT_BLOCK_SIZE = 3;
33	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
34	
35	const COMPONENT_INSURANCE_VALUE = 250;
36	
37	const MAIN_ITEM_INSURANCE_VALUES: Record<string, number> = {
38	  sword: 1000,
39	  amulet: 600,
40	  staff: 800,
41	  potion: 400,
42	};
43	
44	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	};
50	
51	const COMPONENT_TYPES = ["rune", "moonstone"];
52	
53	function isComponent(type: string): boolean {
54	  return COMPONENT_TYPES.includes(type);
55	}
56	
57	function itemBasePremium(type: string): number {
58	  return isComponent(type) ? COMPONENT_BASE_PREMIUM : MAIN_ITEM_BASE_PREMIUMS[type];
59	}
60	
61	function countByType(items: Item[]): Map<string, number> {
62	  const counts = new Map<string, number>();
63	  for (const item of items) {
64	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
65	  }
66	  return counts;
67	}
68	
69	// The MHPCO offers the building block on components. No active example prices a
70	// group of three alike main items, so the size test below is not yet qualified
71	// by `isComponent`; qualify it when such an example is activated.
72	function alikeGroupBasePremium(type: string, count: number): number {
73	  if (count === COMPONENT_BLOCK_SIZE) {
74	    return COMPONENT_BLOCK_BASE_PREMIUM;
75	  }
76	  return count * itemBasePremium(type);
77	}
78	
79	function policyBasePremium(items: Item[]): number {
80	  let total = 0;
81	  for (const [type, count] of countByType(items)) {
82	    total += alikeGroupBasePremium(type, count);
83	  }
84	  return total;
85	}
86	
87	// Which risk surcharges an item's own risk profile earns, as a combined rate.
88	function isHighlyEnchanted(item: Item): boolean {
89	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
90	}
91	
92	function itemSurchargeRate(item: Item): number {
93	  return (
94	    (item.cursed === true ? CURSE_SURCHARGE_RATE : 0) +
95	    (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0)
96	  );
97	}
98	
99	// Item-specific modifiers apply to the base premium of the affected item, not to
100	// the policy total.
101	function itemSurcharges(items: Item[]): number {
102	  return items.reduce(
103	    (total, item) => total + itemSurchargeRate(item) * itemBasePremium(item.type),
104	    0,
105	  );
106	}
107	
108	function isLongStanding(customer: Customer): boolean {
109	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
110	}
111	
112	// Which policy-wide modifiers the customer's standing earns, as a combined signed
113	// rate: discounts are negative, surcharges positive. The first-insurance surcharge
114	// is unconditional -- every quoted item is a first insurance, whatever the
115	// customer's history.
116	function policyWideRate(customer: Customer, precedingContracts: number): number {
117	  return (
118	    (isLongStanding(customer) ? -LOYALTY_DISCOUNT_RATE : 0) +
119	    FIRST_INSURANCE_SURCHARGE_RATE +
120	    (precedingContracts > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0)
121	  );
122	}
123	
124	// The MHPCO stages a premium: item-specific modifiers apply to the base premium
125	// of the affected item, policy-wide modifiers apply to the policy base premium,
126	// and the processing fee is added at the very end.
127	export function quote(customer: Customer, items: Item[], precedingContracts = 0): number {
128	  const basePremium = policyBasePremium(items);
129	  const premiumBeforeFee =
130	    basePremium +
131	    itemSurcharges(items) +
132	    // Policy-wide modifiers apply to the policy base premium, not to any single item.
133	    policyWideRate(customer, precedingContracts) * basePremium;
134	  return premiumBeforeFee + PROCESSING_FEE;
135	}
136	
137	export interface QuoteStep {
138	  op: "quote";
139	  items: Item[];
140	}
141	
142	export interface Damage {
143	  itemType: string;
144	  amount: number;
145	}
146	
147	export interface Incident {
148	  cause: string;
149	  damages: Damage[];
150	}
151	
152	export interface ClaimStep {
153	  op: "claim";
154	  policy: number;
155	  incident: Incident;
156	}
157	
158	export type Step = QuoteStep | ClaimStep;
159	
160	export interface Scenario {
161	  customer: Customer;
162	  steps: Step[];
163	}
164	
165	export interface QuoteResult {
166	  premium: number;
167	}
168	
169	export interface ClaimResult {
170	  payout: number;
171	  remainingCap: number;
172	}
173	
174	export type StepResult = QuoteResult | ClaimResult;
175	
176	// The MHPCO insures each item at its price-list insurance value; the block
177	// discount affects the premium only, not the insurance sum.
178	function itemInsuranceValue(type: string): number {
179	  return isComponent(type) ? COMPONENT_INSURANCE_VALUE : MAIN_ITEM_INSURANCE_VALUES[type];
180	}
181	
182	function insuranceSum(items: Item[]): number {
183	  return items.reduce((total, item) => total + itemInsuranceValue(item.type), 0);
184	}
185	
186	// A policy the MHPCO has written: the items it covers and the payout cap still
187	// available on it.
188	interface Policy {
189	  items: Item[];
190	  remainingCap: number;
191	}
192	
193	const FULL_REIMBURSEMENT_RATE = 1;
194	
195	// The share of a damage the MHPCO reimburses, arbitrating both of its clauses:
196	// damage to a highly enchanted item earns half the damage amount, and damage to
197	// an item of dragon material is fully reimbursed. The 50 % clause wins wherever
198	// both apply, and full reimbursement is what the MHPCO grants anyway, so dragon
199	// material never moves the rate and the decision turns on enchantment alone.
200	function reimbursementRate(item: Item): number {
201	  return (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT
202	    ? REDUCED_REIMBURSEMENT_RATE
203	    : FULL_REIMBURSEMENT_RATE;
204	}
205	
206	// The MHPCO reimburses a damage at the rate its item's clauses earn, less the
207	// deductible that applies to every damage event.
208	// A damage that does not exceed the deductible earns nothing; the MHPCO never
209	// pays out a negative amount.
210	function damagePayout(item: Item, damage: Damage): number {
211	  return Math.max(0, reimbursementRate(item) * damage.amount - DEDUCTIBLE_PER_DAMAGE);
212	}
213	
214	// The MHPCO rounds in its own favour: a payout is rounded down.
215	function roundedPayout(payout: number): number {
216	  return Math.floor(payout);
217	}
218	
219	// The MHPCO writes a policy over the quoted items and opens its payout cap at
220	// twice the insurance sum.
221	function writePolicy(items: Item[]): Policy {
222	  return {
223	    items,
224	    remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum(items),
225	  };
226	}
227	
228	// The insured item a damage report refers to. The MHPCO only reimburses damage
229	// to an item its policy actually covers.
230	function damagedItem(policy: Policy, damage: Damage): Item {
231	  const item = policy.items.find((insured) => insured.type === damage.itemType);
232	  if (item === undefined) {
233	    throw new Error(`The policy does not cover an item of type ${damage.itemType}`);
234	  }
235	  return item;
236	}
237	
238	// What the MHPCO owes for an incident: every damage reimbursed in turn against
239	// its own insured item, the total rounded in the MHPCO's favour.
240	function claimPayout(policy: Policy, incident: Incident): number {
241	  return roundedPayout(
242	    incident.damages.reduce(
243	      (total, damage) => total + damagePayout(damagedItem(policy, damage), damage),
244	      0,
245	    ),
246	  );
247	}
248	
249	// A payout consumes the policy's cap, so successive claims on one policy
250	// accumulate against the same remaining cap.
251	function drawDownCap(policy: Policy, payout: number): number {
252	  policy.remainingCap -= payout;
253	  return policy.remainingCap;
254	}
255	
256	// The total payout per policy is capped at twice the insurance sum, so a claim
257	// is reduced to whatever cap the policy has left.
258	function settleClaim(policy: Policy, incident: Incident): ClaimResult {
259	  const payout = Math.min(claimPayout(policy, incident), policy.remainingCap);
260	  return { payout, remainingCap: drawDownCap(policy, payout) };
261	}
262	
263	// The MHPCO rounds in its own favour: a premium is rounded up, and only the
264	// final amount is rounded -- intermediate amounts stay fractional.
265	function roundedPremium(premium: number): number {
266	  return Math.ceil(premium);
267	}
268	
269	// Only a quote writes a contract. A claim is settled against a contract the
270	// MHPCO already holds, so it does not move the customer towards the follow-up
271	// contract discount.
272	function writesContract(step: Step): step is QuoteStep {
273	  return step.op === "quote";
274	}
275	
276	// A scenario is one customer's sequence of operations, processed in order. Each
277	// step is quoted against the number of contracts that preceded it, so every
278	// contract after the customer's first earns the follow-up-contract discount.
279	export function runScenario(scenario: Scenario): { results: StepResult[] } {
280	  const results: StepResult[] = [];
281	  const policies = new Map<number, Policy>();
282	  let precedingContracts = 0;
283	  scenario.steps.forEach((step, index) => {
284	    if (writesContract(step)) {
285	      results.push({
286	        premium: roundedPremium(quote(scenario.customer, step.items, precedingContracts)),
287	      });
288	      policies.set(index, writePolicy(step.items));
289	      precedingContracts += 1;
290	    } else {
291	      const policy = policies.get(step.policy);
292	      if (policy === undefined) {
293	        throw new Error(`Claim refers to step ${String(step.policy)}, which wrote no policy`);
294	      }
295	      results.push(settleClaim(policy, step.incident));
296	    }
297	  });
298	  return { results };
299	}
